(()=>{
 const $=s=>document.querySelector(s),stages=[['new','Novo lead'],['contact','Em contato'],['meeting','Reunião'],['proposal','Proposta'],['negotiation','Negociação'],['won','Ganho'],['lost','Perdido']];
 const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),date=v=>new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
 let team=[],items=[],stats=[],cursor=null,current=null,requestId,taskRequestId,formDirty=false,generation=0,loading=false;
 const api=(...args)=>window.awCRM.api(...args),node=(...args)=>window.awCRM.node(...args),action=(...args)=>window.awCRM.action(...args);
 const field=name=>$('#crm-form').elements.namedItem(name);
 function options(select,people,blank='Sem responsável'){select.replaceChildren();if(blank!==null){const o=node('option',blank);o.value='';select.append(o);}for(const p of people){const o=node('option',p.name);o.value=p.email;select.append(o);}}
 async function getTeam(){const g=generation;const data=await api('/api/admin/crm/team');if(g!==generation)return;team=data.items;options($('#crm-owner'),team,'Todos');}
 window.crmLoad=async(append=false)=>{
  if(loading)return;loading=true;const g=generation;$('#crm-status').textContent='Carregando oportunidades…';try{
   if(!team.length)await getTeam();const q=new URLSearchParams({search:$('#crm-search').value,assignee:$('#crm-owner').value});if(append&&cursor)q.set('before',cursor);
   const data=await api('/api/admin/crm/leads?'+q);if(g!==generation)return;items=append?[...items,...data.items]:data.items;stats=data.stats;cursor=data.next;$('#crm-more').hidden=!cursor;render();$('#crm-status').textContent=cursor?'Há mais oportunidades. Use Carregar mais para exibir todas.':items.length?'':'Nenhuma oportunidade encontrada. Cadastre um lead ou aguarde um pedido do site.';
  }catch(e){if(g===generation)$('#crm-status').textContent=e.message;}finally{if(g===generation)loading=false;}
 };
 function render(){
  const totals=Object.fromEntries(stats.map(s=>[s.crm_stage,s])),count=stats.reduce((n,s)=>n+s.count,0),open=stats.filter(s=>!['won','lost'].includes(s.crm_stage)).reduce((n,s)=>n+Number(s.value),0);
  $('#crm-metrics').replaceChildren();for(const [label,value] of [['Oportunidades',count],['Valor em aberto',money(open)],['Ganhos',money(totals.won?.value||0)],['Negócios ganhos',totals.won?.count||0]]){const c=node('article',undefined,'crm-metric');c.append(node('span',label),node('strong',String(value)));$('#crm-metrics').append(c);}
  $('#crm-board').replaceChildren();for(const [stage,label] of stages){const column=node('section',undefined,'crm-column');const head=node('div',undefined,'crm-column-head');head.append(node('h3',label),node('span',String(totals[stage]?.count||0)),node('p',money(totals[stage]?.value||0)));column.append(head);
   for(const lead of items.filter(x=>x.crm_stage===stage)){const c=node('article',undefined,'crm-lead');c.append(action(lead.company||lead.name,()=>window.crmOpen(lead.id)),node('p',lead.company?lead.name:lead.service),node('strong',money(lead.estimated_value)),node('p',team.find(x=>x.email===lead.assignee)?.name||'Sem responsável'),node('small',lead.origin));column.append(c);}if(!items.some(x=>x.crm_stage===stage))column.append(node('p',totals[stage]?.count?'Carregue mais para ver os cartões.':'Nenhuma oportunidade.','hint'));$('#crm-board').append(column);
  }
 }
 function setStageOptions(){const select=field('crmStage');select.replaceChildren();for(const [value,label]of stages){const o=node('option',label);o.value=value;select.append(o);}}
 function showForm(lead){current=lead;formDirty=false;requestId=crypto.randomUUID();taskRequestId=crypto.randomUUID();setStageOptions();options(field('assignee'),team);options($('#crm-task-form').elements.namedItem('assignee'),team,null);
  const values=lead?{...lead,website:lead.contact_website,crmStage:lead.crm_stage,value:lead.estimated_value,expectedClose:lead.expected_close?String(lead.expected_close).slice(0,10):''}:{name:'',company:'',email:'',phone:'',website:'',service:'',origin:'Prospecção',crmStage:'new',assignee:window.awCRM.getProfile().email,value:0,expectedClose:'',idea:''};
  for(const name of ['name','company','email','phone','website','service','origin','crmStage','assignee','value','expectedClose','idea'])field(name).value=values[name]??'';
  if(values.assignee&&!team.some(x=>x.email===values.assignee)){const o=node('option',values.assignee+' (inativo)');o.value=values.assignee;field('assignee').append(o);field('assignee').value=values.assignee;}
  $('#crm-task-form').reset();$('#crm-task-form').elements.namedItem('assignee').value=window.awCRM.getProfile().email;$('#crm-event-form').reset();$('#crm-title').textContent=lead?'Ficha da oportunidade':'Novo lead';$('#crm-detail').hidden=!lead;$('#crm-form-status').textContent='';$('#crm-contact-links').replaceChildren();
  if(lead?.email){const a=node('a','Enviar e-mail');a.href='mailto:'+lead.email;$('#crm-contact-links').append(a);}const phone=(lead?.phone||'').replace(/\D/g,'');if(phone.length>=10&&phone.length<=15){const a=node('a','Abrir WhatsApp');a.href='https://wa.me/'+(phone.length<=11?'55':'')+phone;a.target='_blank';a.rel='noopener';$('#crm-contact-links').append(a);}if(lead?.notes)$('#crm-contact-links').append(node('p','Anotação do orçamento: '+lead.notes));
  if(!$('#crm-dialog').open)$('#crm-dialog').showModal();
 }
 window.crmOpen=async id=>{if(formDirty&&!confirm('Descartar as alterações ainda não salvas desta ficha?'))return;try{const g=generation;if(!team.length)await getTeam();if(g!==generation)return;const data=await api('/api/admin/crm/leads/'+id);if(g!==generation)return;showForm(data.lead);renderDetail(data);}catch(e){window.awCRM.notice(e.message,true);}};
 function renderDetail(data){$('#crm-events').replaceChildren();const received=node('article',undefined,'crm-event');received.append(node('strong','Cadastro da oportunidade'),node('p',data.lead.idea||'Sem descrição inicial.'),node('small',date(data.lead.created_at)));$('#crm-events').append(received);
  for(const e of data.events){const c=node('article',undefined,'crm-event');c.append(node('strong',({note:'Observação',call:'Conversa',meeting:'Reunião',proposal:'Proposta',created:'Cadastro',updated:'Ficha atualizada',task:'Tarefa',imported:'Recebimento'})[e.kind]||e.kind),node('p',e.body),node('small',date(e.created_at)+' · '+(team.find(x=>x.email===e.actor)?.name||e.actor)));$('#crm-events').append(c);}
  $('#crm-tasks').replaceChildren();for(const t of data.tasks){const c=node('article',undefined,'crm-task');c.classList.toggle('done',t.done);c.append(node('strong',t.title),node('p',date(t.due_at)+' · '+(team.find(x=>x.email===t.assignee)?.name||t.assignee)),action(t.done?'Reabrir':'Concluir',async()=>{await api('/api/admin/crm/tasks/'+t.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({done:!t.done,revision:t.revision})});await reloadDetail();}));$('#crm-tasks').append(c);}if(!data.tasks.length)$('#crm-tasks').append(node('p','Nenhuma tarefa agendada.','hint'));
 }
 async function reloadDetail(){const g=generation,id=current?.id;if(!id)return;const data=await api('/api/admin/crm/leads/'+id);if(g===generation&&current?.id===id)renderDetail(data);}
 $('#crm-new').addEventListener('click',async()=>{try{const g=generation;if(!team.length)await getTeam();if(g!==generation)return;showForm(null);}catch(e){window.awCRM.notice(e.message,true);}});
 $('#crm-refresh').addEventListener('click',()=>window.crmLoad());$('#crm-more').addEventListener('click',()=>window.crmLoad(true));
 function close(){if(formDirty&&!confirm('Descartar alterações não salvas?'))return;$('#crm-dialog').close();formDirty=false;}
 $('#crm-close').addEventListener('click',close);$('#crm-dialog').addEventListener('cancel',e=>{e.preventDefault();close();});
 $('#crm-form').addEventListener('input',()=>formDirty=true);window.addEventListener('beforeunload',e=>{if(formDirty){e.preventDefault();e.returnValue='';}});
 $('#crm-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;$('#crm-form-status').textContent='Salvando…';const data=Object.fromEntries(new FormData(form));data.value=Number(data.value);if(current)data.revision=current.revision;else data.requestId=requestId;try{const result=await api('/api/admin/crm/leads'+(current?'/'+current.id:''),{method:current?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});formDirty=false;await window.crmOpen(current?.id||result.id);$('#crm-form-status').textContent='Oportunidade salva.';window.crmLoad();}catch(err){$('#crm-form-status').textContent=err.message;}finally{button.disabled=false;}});
 async function submitDetail(e,type){e.preventDefault();if(!current)return;const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));if(type==='tasks'){data.requestId=taskRequestId;data.dueAt=new Date(data.dueAt+':00-03:00').toISOString();}try{await api('/api/admin/crm/leads/'+current.id+'/'+type,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});form.reset();if(type==='tasks'){taskRequestId=crypto.randomUUID();form.elements.namedItem('assignee').value=window.awCRM.getProfile().email;}await reloadDetail();$('#crm-form-status').textContent=type==='tasks'?'Tarefa agendada.':'Atividade registrada.';}catch(err){$('#crm-form-status').textContent=err.message;}finally{button.disabled=false;}}
 $('#crm-task-form').addEventListener('submit',e=>submitDetail(e,'tasks'));$('#crm-event-form').addEventListener('submit',e=>submitDetail(e,'events'));
 window.crmClear=()=>{generation++;loading=false;team=[];items=[];current=null;formDirty=false;$('#crm-dialog').close();$('#crm-form').reset();$('#crm-task-form').reset();$('#crm-event-form').reset();for(const id of ['crm-board','crm-metrics','crm-events','crm-tasks','crm-contact-links'])$('#'+id).replaceChildren();};
})();
